# --- 목과 스파이 ---

@Test
void mockDoesNothing() {
    MailSendClient mock = mock(SmtpMailSendClient.class);

    boolean result = mock.sendEmail("a", "b", "c", "d");

    System.out.println(">>> mock: " + result);
}

@Test
void spyRunsReal() {
    SmtpMailSendClient spy = spy(new SmtpMailSendClient());

    boolean result = spy.sendEmail("a", "b", "c", "d");

    System.out.println(">>> spy: " + result);
}

