#   스파이는 진짜로 보냈다

# --- given 을 스파이에 쓰면 ---

@Test
void spyWithGiven() {
    SmtpMailSendClient spy = spy(new SmtpMailSendClient());

    given(spy.sendEmail(any(), any(), any(), any())).willReturn(true);

    boolean result = spy.sendEmail("a", "b", "c", "d");

    assertThat(result).isTrue();
}

