#   통과했다

#   그런데 SMTP 로그가 있다

#   given(spy.sendEmail(...)) 를 평가하면서 진짜로 보냈다

#   메일을 안 보내려고 스파이를 썼는데 보냈다

# --- doReturn 으로 바꾸면 ---

@Test
void spyWithDoReturn() {
    SmtpMailSendClient spy = spy(new SmtpMailSendClient());

    doReturn(true).when(spy).sendEmail(any(), any(), any(), any());

    boolean result = spy.sendEmail("a", "b", "c", "d");

    assertThat(result).isTrue();
}

