@Test
void mockBothWork() {
    MailSendClient mock1 = mock(MailSendClient.class);
    given(mock1.sendEmail(any(), any(), any(), any())).willReturn(true);

    MailSendClient mock2 = mock(MailSendClient.class);
    doReturn(true).when(mock2).sendEmail(any(), any(), any(), any());

    System.out.println(">>> " + mock1.sendEmail("","","",""));
    System.out.println(">>> " + mock2.sendEmail("","","",""));
}

