        return sendSlack(message);                 // 막고 싶다
    }

    protected String buildMessage(Order order) {
        return "주문 " + order.getId() + " / " + order.getTotalPrice() + "원";
    }

    protected boolean sendSlack(String message) {
        // 진짜 슬랙 전송
    }
}

@Test
void spyPartial() {
    NotificationService spy = spy(new NotificationService());
    doReturn(true).when(spy).sendSlack(anyString());

    boolean result = spy.notifyOrder(createOrder(1L, 8500));

    assertThat(result).isTrue();
    verify(spy).sendSlack("주문 1 / 8500원");
}

$ ./gradlew test --tests SpyTest

SpyTest > spyPartial() PASSED

#   buildMessage 는 진짜로 돌았다
#   sendSlack 은 막혔다

