# --- 목으로 하면 ---

@Test
void mockPartial() {
    NotificationService mock = mock(NotificationService.class);
    doReturn(true).when(mock).sendSlack(anyString());

    boolean result = mock.notifyOrder(createOrder(1L, 8500));

    System.out.println(">>> " + result);
}

>>> false

#   notifyOrder 도 가짜라 아무것도 안 한다

#   buildMessage 를 검증할 수가 없다

# --- 그런데 이 설계가 맞나 ---

#   buildMessage 와 sendSlack 이 한 클래스에 있다

#   나누면

public class NotificationService {
    private final SlackClient slackClient;      // 인터페이스

    public boolean notifyOrder(Order order) {
        return slackClient.send(MessageBuilder.build(order));
    }
}

@Test
void withoutSpy() {
    given(slackClient.send(anyString())).willReturn(true);

    boolean result = notificationService.notifyOrder(createOrder(1L, 8500));

    assertThat(result).isTrue();
    verify(slackClient).send("주문 1 / 8500원");
}

SpyTest > withoutSpy() PASSED

#   스파이가 필요 없어졌다

#   MessageBuilder 는 순수 함수라 따로 단위 테스트한다  (2.7절)

#   '스파이를 쓰고 싶다' 가 설계 신호였다

